func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
	originURL := ""
	if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
		originURL = resolvedOriginURL
	}

	s, err := settings.Load(ctx)
	if err != nil {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr == nil {
			logFallback(ctx, "push", fallbackURL, "load settings", err,
				slog.String("push_remote", pushRemoteName),
			)
			return fallbackURL, false, nil
		}
		return "", false, fmt.Errorf("load settings: %w", err)
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr != nil {
			return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
		}
		return fallbackURL, false, nil
	}

	// Every push URL, not just the first: git fans out to all of them on the
	// git-branch backend, so ownership has to hold for the whole set. The first
	// still drives transport derivation below, matching the single destination
	// resolveRefsPushDestination sends checkpoint refs to.
	pushRemoteURLs, err := GetPushURLs(ctx, pushRemoteName)
	if err != nil {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr == nil {
			logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
				slog.String("push_remote", pushRemoteName),
			)
			return fallbackURL, false, nil
		}
		return "", true, fmt.Errorf("no push URL found: %w", err)
	}
	pushRemoteURL := pushRemoteURLs[0]

	// Whether to use the checkpoint remote at all is a question about ownership
	// ("is this checkpoint_remote mine, or did I inherit it by cloning?"), which
	// both remotes get a vote on: origin says which project this is, the push
	// destinations say which repos we are writing to. Any one of them owned by
	// somebody other than the checkpoint repo's owner means inherited. See
	// checkpointRemoteIsInherited.
	if inherited, reason := checkpointRemoteIsInherited(ctx, config, originURL, pushRemoteURLs); inherited {
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr != nil {
			return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
		}
		logging.Warn(ctx, "checkpoint-remote: ignoring checkpoint_remote that appears to belong to another owner; pushing checkpoints to the push remote instead",
			slog.String("checkpoint_repo", config.Repo),
			slog.String("reason", reason),
			slog.String("hint", "if this checkpoint repo is yours, configure checkpoint_remote in .entire/settings.local.json"),
		)
		return fallbackURL, false, nil
	}

	pushInfo, err := ParseURL(pushRemoteURL)
	if err != nil {
		if originURL != "" {
			logFallback(ctx, "push", originURL, "parse push remote URL", err,
				slog.String("push_remote", pushRemoteName),
			)
			return originURL, false, nil
		}
		return "", true, fmt.Errorf("no push URL found: %w", err)
	}
	withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
	if withToken && isDirectGitTransport(pushInfo.Protocol) {
		// Coerce a direct (ssh/https) remote to HTTPS so the token applies,
		// keeping the host so enterprise installations stay on their own host.
		// An entire:// remote carries a cluster host that isn't a usable HTTPS
		// host, so it's handled separately after the owner check below.
		//
		// Keep the port only when the source was already HTTPS. SSH ports
		// (e.g., :2222) don't map to HTTPS ports on the same host.
		port := ""
		if pushInfo.Protocol == ProtocolHTTPS {
			port = pushInfo.Port
		}
		pushInfo = &Info{
			Protocol: ProtocolHTTPS,
			Host:     pushInfo.Host,
			Port:     port,
			Owner:    pushInfo.Owner,
			Repo:     pushInfo.Repo,
		}
	}

	if withToken && pushInfo.Protocol == ProtocolEntire {
		// The checkpoint token is an HTTPS credential for the provider host;
		// it can't ride through the entire:// helper (which does its own
		// auth). Route to the provider over HTTPS instead of the mirror.
		if providerURL, ok := resolveProviderCheckpointURL(ctx, config, ""); ok {
			return providerURL, true, nil
		}
	}

	pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
	if err != nil {
		// The push remote's protocol can't be mapped to a checkpoint URL
		// (e.g. file://, or an entire:// mirror of a different forge than the
		// configured provider). Honor the configured checkpoint_remote by
		// targeting the provider's canonical host over HTTPS rather than
		// misrouting checkpoints to the origin remote.
		if providerURL, ok := resolveProviderCheckpointURL(ctx, config, ""); ok {
			return providerURL, true, nil
		}
		fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
		if fallbackErr == nil {
			logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
				slog.String("push_remote", pushRemoteName),
			)
			return fallbackURL, false, nil
		}
		return "", true, fmt.Errorf("no push URL found: %w", err)
	}

	return pushURL, true, nil
}

//	fork first, clone the fork  -> origin <fork>/app          -> origin mismatches
//	clone the base, add a fork  -> origin <upstream>/app       -> origin MATCHES
//
// In the second, origin belongs to upstream rather than to us, so an
// origin-only check reads an inherited setting as ours and aims a
// contributor's transcripts at the upstream project's checkpoint repo. The push
// destination is the signal that disagrees: we are writing to <fork>/app.
//
// The cost, accepted deliberately: a repo of our own with a differently-owned
// secondary remote (a backup in another org) no longer routes checkpoints to
// our checkpoint repo on pushes to THAT remote — the two topologies are
// indistinguishable from local git config alone, since both are
// origin=<owner>/app plus a push destination owned by somebody else, and only
// the network could say which repo is ours. Pushes to the elected sync remote
// (normally origin) are unaffected, and ENT-1451's pre-push gate independently
// blocks checkpoint sync on pushes to a non-elected remote, so this costs
// nothing that the gate was not already stopping. Erring toward "not ours" is
// the safe direction: it never writes session transcripts to a repository we
// cannot confirm we own.
//
// A remote with several push URLs must have EVERY one of them owned by the
// checkpoint repo's owner. git fans out to all of them on the git-branch
// backend, so checking only the first would let a differently-owned mirror in
// second position read as ours.
//
// An identity whose owner cannot be determined (no remote at all, or a
// non-forge URL such as a bare local path) counts as inherited: for a committed
// setting we cannot confirm ownership, and falling back preserves the previous
// behavior for those repos. settings.local.json is the escape hatch when the
// checkpoint repo is genuinely ours but owned by a different account or org.
func checkpointRemoteIsInherited(ctx context.Context, config *settings.CheckpointRemoteConfig, originURL string, pushRemoteURLs []string) (bool, string) {
	checkpointOwner := config.Owner()
	if checkpointOwner == "" {
		// No owner to compare (malformed repo field). Matches the predecessor,
		// which skipped the check rather than blocking on it.
		return false, ""
	}
	if settings.CheckpointRemoteIsLocalOnly(ctx) {
		return false, ""
	}

	// Both identities when both exist. A repo with no origin has exactly one
	// identity — its push remote — and must not lose its configured checkpoint
	// remote just because nothing is named "origin".
	identities := make([]struct{ url, source string }, 0, 1+len(pushRemoteURLs))
	if originURL != "" {
		identities = append(identities, struct{ url, source string }{originURL, "origin"})
	}
	for _, pushRemoteURL := range pushRemoteURLs {
		if pushRemoteURL != "" && pushRemoteURL != originURL {
			identities = append(identities, struct{ url, source string }{pushRemoteURL, "push remote"})
		}
	}
	if len(identities) == 0 {
		return true, "no remote to establish ownership"
	}

	for _, id := range identities {
		info, err := ParseURL(id.url)
		if err != nil || info.Owner == "" {
			return true, id.source + " URL owner could not be determined"
		}
		if !strings.EqualFold(info.Owner, checkpointOwner) {
			return true, fmt.Sprintf("%s owner %q differs from checkpoint owner %q", id.source, info.Owner, checkpointOwner)
		}
	}
	return false, ""
}

// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
	url, err := gitremote.GetRemoteURLInDir(ctx, dir, remoteName)
	if err != nil {
		return "", fmt.Errorf("get remote URL: %w", err)
	}
	return url, nil
}

// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
func ParseURL(rawURL string) (*Info, error) {
	info, err := gitremote.ParseURL(rawURL)
	if err != nil {
		return nil, fmt.Errorf("parse URL: %w", err)
	}
	return info, nil
}

// isDirectGitTransport reports whether the protocol talks to the git host
// directly over ssh/https (where the host is a usable HTTPS host for token
// auth), as opposed to a remote helper scheme like entire:// or a local
// file://.
func isDirectGitTransport(protocol string) bool {
	return protocol == ProtocolSSH || protocol == ProtocolHTTPS
}

func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
	switch info.Protocol {
	case ProtocolSSH:
		// SCP-style (git@host:repo) doesn't support ports. When a non-default
		// port is set (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
		if info.Port != "" {
			return fmt.Sprintf("ssh://git@%s/%s.git", info.HostPort(), config.Repo), nil
		}
		return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
	case ProtocolHTTPS:
		return fmt.Sprintf("https://%s/%s.git", info.HostPort(), config.Repo), nil
	case ProtocolEntire:
		// entire:// push-through mirrors are cluster-scoped: keep the cluster
		// host and forge segment, swap in the checkpoint repo. Only derivable
		// when the forge maps back to the configured provider's host, so a
		// github checkpoint_remote never routes through another forge's mirror.
		host, ok := providerHost(config.Provider)
		if !ok || !strings.EqualFold(info.CanonicalHost(), host) {
			return "", fmt.Errorf("entire:// remote forge %q does not match checkpoint provider %q", info.Forge, config.Provider)
		}
		return fmt.Sprintf("entire://%s/%s/%s", info.HostPort(), info.Forge, config.Repo), nil
	default:
		return "", fmt.Errorf("unsupported protocol %q in remote URL", info.Protocol)
	}
}

// resolveProviderCheckpointURL builds the checkpoint URL for the configured
// provider, choosing the transport from what's already configured for that
// endpoint. It is the fallback used when the push/origin remote's protocol can't
// be mapped to a git transport (e.g. entire://, file://): the configured
// checkpoint_remote names a concrete provider, so checkpoints go there rather
package strategy

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// refsPushDestination is the single place checkpoint refs are pushed to.
type refsPushDestination struct {
	// target is passed to git push and to the recovery fetch: a remote name, or a URL.
	target string
	// checkpointRemote records that target came from a configured
	// checkpoint_remote. It cannot be recovered from target's shape — a
	// resolved push URL is URL-shaped too — and it decides both how the
	// destination is named and whether the "a checkpoint remote is configured"
	// hint applies.
	checkpointRemote bool
	// ignoredPushURLs counts the push URLs of a multi-URL remote that will NOT
	// receive checkpoint refs. Zero in every single-destination topology.
	ignoredPushURLs int
}

// resolveRefsPushDestination picks the single destination for checkpoint-ref
// pushes.
//
// Checkpoint refs need ONE deterministic destination, because the push-discovery
// queue records only a ref (`{"ref": …}`) with no per-destination state: a ref is
// removed from the queue once "the push" succeeds, so "the push" has to mean one
// place. Relying on git's fan-out across a remote's several push URLs breaks that
// in both directions — a single failing URL fails the whole invocation and no ref
// unqueues even though some URLs took it, and an unreachable FIRST URL makes git
// die() before it reaches any later URL at all.
//
// So when a remote carries more than one push URL we target its first push URL
// directly (the one git itself would push to first) and ignore the rest. The
// recovery fetch in fetchAndRebaseRefCommon uses the same target, so — unlike the
// fan-out path, which reconciled the remote's FETCH url while pushing to its
// pushurls — the URL we reconcile is finally the URL we push to.
//
// Consequences, deliberately accepted:
//   - Checkpoint refs live in exactly one repository. Cloning that repository
//     resolves them (its url becomes the clone's fetch URL); cloning a different
//     mirror of the same code does not. Mirroring checkpoints to several
//     repositories is what checkpoint_remote is for.
//   - A first push URL that REJECTS a ref (non-fast-forward) no longer lets later
//     URLs receive it. git would have carried on to them; we stop. That is the
//     price of a deterministic destination, and it is the case the queue can
//     actually reason about.
//
// The git-branch backend deliberately keeps git's fan-out: its v1 branch is a
// single shared ref with no queue to keep coherent, and mirroring it to every
// push URL is behavior users configure their remotes for.
//
// A single push URL keeps the remote NAME as the target rather than resolving it
// to a URL, so the overwhelmingly common topology behaves exactly as before —
// remote-tracking refs still update, output still says "origin", and no
// URL-keyed promisor config appears.
//
// Call this only once there is something to push: it spawns `git remote get-url`
// and its result is unused on an empty queue.
func resolveRefsPushDestination(ctx context.Context, ps pushSettings) refsPushDestination {
	target := ps.pushTarget()

	// A configured checkpoint_remote, or a push straight to a URL (git hands the
	// hook a bare URL verbatim), is already a single explicit destination.
	if ps.hasCheckpointURL() || remote.IsURL(target) {
		return refsPushDestination{target: target, checkpointRemote: ps.hasCheckpointURL()}
	}

	urls, err := remote.GetPushURLs(ctx, target)
	if err != nil {
		// Not a configured remote, or git could not report its URLs. Keep the
		// target as given; the push itself will report any real problem.
		logging.Debug(ctx, "git-refs push: could not enumerate push URLs; using target as given",
			slog.String("target", target),
			slog.String("error", err.Error()),
		)
	}
	if len(urls) < 2 {
		return refsPushDestination{target: target}
	}
	return refsPushDestination{target: urls[0], ignoredPushURLs: len(urls) - 1}
}

// display names the destination for progress and warning output.
//
// Deliberately not displayPushTarget: that maps ANY URL to the literal words
// "checkpoint remote", which was only ever true because a URL target implied a
// configured checkpoint_remote. A push URL we resolved ourselves is URL-shaped
// but is not a checkpoint remote, so it is named by its (redacted) URL.
func (d refsPushDestination) display() string {
	switch {
	case d.checkpointRemote:
		return "checkpoint remote"
	case d.ignoredPushURLs > 0:
		return fmt.Sprintf("%s (first of %d push URLs)", remote.RedactURLOrPath(d.target), d.ignoredPushURLs+1)
	default:
		return remote.RedactURLOrPath(d.target)
	}
}

// warnIgnoredPushURLs tells the user that checkpoint refs are going to one URL of
// a multi-URL remote — otherwise the choice is invisible and looks like the other
// mirrors silently lost their checkpoints. Call it only when there are refs to
// push, so a no-op push stays quiet.
func (d refsPushDestination) warnIgnoredPushURLs(ctx context.Context) {
	if d.ignoredPushURLs == 0 {
		return
	}
	fmt.Fprintf(stderrWriter, "[entire] Checkpoints go to one repository: %s. %d other push URL(s) of this remote will not receive them.\n",
		d.display(), d.ignoredPushURLs)
	}
	return enabled
}

// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
type CheckpointRemoteConfig struct {
	Provider string // e.g., "github"
	Repo     string // e.g., "org/checkpoints-repo"
}

// Owner returns the owner portion of the repo field (before the slash).
// Returns empty string if the repo field doesn't contain a slash.
func (c *CheckpointRemoteConfig) Owner() string {
	parts := strings.SplitN(c.Repo, "/", 2)
	if len(parts) < 2 {
		return ""
	}
	return parts[0]
}

// HasCheckpointRemoteKey reports whether a checkpoint_remote entry exists in
// strategy options at all — deliberately including malformed entries that
// GetCheckpointRemote rejects (it returns nil for absent AND malformed, so it
// cannot distinguish "no intent" from "botched intent"). Presence in any form
// means the user intends a checkpoint remote.
func (s *EntireSettings) HasCheckpointRemoteKey() bool {
	if s.StrategyOptions == nil {
		return false
	}
	_, ok := s.StrategyOptions["checkpoint_remote"]
	return ok
}

// CheckpointRemoteIsLocalOnly reports whether a checkpoint_remote entry is
// present in .entire/settings.local.json.
//
// That file is gitignored and per-clone, so a checkpoint_remote living there
// is this developer's own explicit choice. Callers use this to distinguish
// "I configured where my checkpoints go" from "I inherited a committed setting
// that points at the upstream project's checkpoint repo".
//
// The filename alone does not establish that — see localLayerTrackedReason.
// This reads the file directly rather than through Load, so it repeats the
// tracked check the loader applies to the local layer —
// without it, the ownership signal this gates could be inherited from the very
// upstream it is meant to distinguish.
//
// Best-effort: an unreadable, malformed, or unverifiable local file reports
// false, which is the conservative answer (callers then fall back to weaker
// ownership signals).
func CheckpointRemoteIsLocalOnly(ctx context.Context) bool {
	path, raw, exists, err := LoadLocalRaw(ctx)
	if err != nil || !exists {
		return false
	}
	if classifyLocalSettings(ctx, path) != localOwn {
		return false
	}
	return rawHasKey(raw, "strategy_options", "checkpoint_remote")
}

// GetCheckpointRemote returns the configured checkpoint remote.
// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
// Returns nil if not configured, wrong type, or missing required fields.
func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
	if s.StrategyOptions == nil {
		return nil
	}
	val, ok := s.StrategyOptions["checkpoint_remote"]
	if !ok {
		return nil
	}
	m, ok := val.(map[string]any)
	if !ok {
		return nil
	}
	provider, providerOK := m["provider"].(string)
	repo, repoOK := m["repo"].(string)
	if !providerOK || !repoOK || provider == "" || repo == "" {
		return nil
	}
	if !strings.Contains(repo, "/") {
		return nil
	}
	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
}

// GetCheckpointPushRemote returns the configured checkpoint push remote name.
// Stored in strategy_options.checkpoint_push_remote as a plain git remote
// name (e.g. "origin", "private"). This selects WHICH configured remote
// carries checkpoint data — distinct from checkpoint_remote, which derives a
// dedicated URL. Returns "" if unset, empty, or not a string.
func (s *EntireSettings) GetCheckpointPushRemote() string {
	if s.StrategyOptions == nil {
		return ""
	}
	val, ok := s.StrategyOptions["checkpoint_push_remote"].(string)
	if !ok {
		return ""
	}
	return val
}

