// so no reachability check is needed here.
func resolvePushSettings(ctx context.Context, pushRemoteName string) pushSettings {
	s, err := settings.Load(ctx)
	if err != nil {
		return pushSettings{remote: pushRemoteName}
	}

	ps := pushSettings{
		remote:        pushRemoteName,
		pushDisabled:  s.IsPushSessionsDisabled(),
		primaryIsRefs: primaryIsGitRefs(ctx),
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return ps
	}
	checkpointURL, enabled, err := remote.PushURL(ctx, pushRemoteName)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not derive URL from push remote",
			slog.String("remote", pushRemoteName),
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ps
	}
	if !enabled || checkpointURL == "" {
		return ps
	}

	ps.checkpointURL = checkpointURL

	// If the v1 checkpoint branch doesn't exist locally, try to fetch it from the URL.
	// This is a one-time operation — once the branch exists locally, subsequent pushes
	// skip the fetch entirely. Only fetch the metadata branch; trails are always pushed
	// to the user's push remote, not the checkpoint remote.
	//
	// Skipped entirely under the git-refs primary backend, where the "one-time"
	// framing does not hold: that backend pushes per-checkpoint refs and never
	// writes the local v1 branch (see prePush), so the branch stays missing
	resolveCtx, resolveSpan := perf.Start(ctx, "resolve_push_settings")
	ps := resolvePushSettings(resolveCtx, remote)
	resolveSpan.End()

	if ps.pushDisabled {
		return nil
	}

	// Single-remote gate (ENT-1451): checkpoint data syncs only to the
	// elected checkpoint sync remote. A dedicated checkpoint_remote URL is
	// exempt — it is a dedicated metadata store addressed directly, not a
	// remote selected by this push. The gate must stay BELOW
	// resolvePushSettings: hasCheckpointURL is only known after resolution,
	// so hoisting the gate above it would break the exemption.
	//
	// Capture is two-phase, straddling this whole function. The proposal runs
	// before the gate so that the push which elects a remote by evidence (push
	// target agrees with the branch's declared push destination) is also the
	// first push to carry checkpoints there; the election is persisted only at
	// the delivery points below, once those checkpoints actually arrived.
	// Everything in between can still stop delivery, and the election is
	// permanent, so intent is not enough to move it. The hint below then speaks
	// only for what capture left gated — see hintGatedCheckpointSync.
	var pendingCapture string
	if !ps.hasCheckpointURL() {
		if pendingCaptureCheckpointSyncRemote(ctx, ps.remote) {
			pendingCapture = ps.remote
		}
		if !checkpointSyncAllowedForRemote(ctx, ps.remote, pendingCapture) {
			hintGatedCheckpointSync(ctx, ps.remote)
			return nil
		}
	}

	// git-refs primary: push the per-checkpoint refs recorded in the push queue
	// instead of the single v1 branch. Those refs live under refs/entire/, not
	// refs/heads/, so a forge can never pick them as a repository's default
	// branch — the empty-remote guard below is unnecessary for this backend.
	// (A configured git-branch mirror's v1 ref is not pushed here yet — mirror
	// push for downgrade safety is a later step.)
	if ps.primaryIsRefs {
		return s.prePushCheckpointRefs(ctx, ps, pendingCapture)
	}
// checkpointBlobFetchTargets returns the ordered fetch targets for blob
// hydration. A configured checkpoint_remote is a dedicated store with a single
// authoritative target; otherwise each checkpoint read candidate becomes a
// target (its URL when resolvable — reusing the checkpoint-token URL
// derivation — else the bare remote name). An empty candidate chain keeps the
// legacy single-target shape so error reporting matches today's remoteless
// behavior.
func checkpointBlobFetchTargets(ctx context.Context) []string {
	if remote.Configured(ctx) {
		return []string{resolveCheckpointFetchTarget(ctx)}
	}
	candidates := strategy.CheckpointReadRemotes(ctx)
	if len(candidates) == 0 {
		return []string{resolveCheckpointFetchTarget(ctx)}
	}
	targets := make([]string, 0, len(candidates))
	for _, name := range candidates {
		targets = append(targets, remote.CheckpointFetchTargetFrom(ctx, name))
	}
	return targets
}
