{"chunk_id":"ac2703","wall_time_seconds":1.001632458,"session_id":42653,"original_token_count":2505,"output":"// Package ingest implements the NATS-driven indexing pipeline: parse
// repo_refs_v1 events, fetch commits via the Repo API, embed via Cohere,
// upsert into Turbopuffer, fan-out residency-safe pointers via the
// shared forwarder, and update activity counters.
package ingest

import (
	"encoding/json"
	"fmt"
	"time"
)

// supportedEnvelopeVersion is the wire-protocol version we accept.
// Mirrors tlog-viewer/internal/tlog. Reject everything else so a future
// wire change is loud.
const supportedEnvelopeVersion = 1

// RefEvent is the parsed payload of a repo_refs_v1.{repo_id} message.
type RefEvent struct {
	Sequence  int64     `json:"sequence"`
	RepoID    string    `json:"repo_id"`
	RefName   string    `json:"ref_name"`
	RefOp     string    `json:"ref_op"`
	OldTarget string    `json:"old_target"`
	NewTarget string    `json:"new_target"`
	Timestamp time.Time `json:"timestamp"`
	// PusherID is the authenticated pusher's account ULID — the one residency-safe
	// identity on the event (immutable; placement is resolved from it at ingest,
	// never carried here). Empty for service / non-user pushes → unattributed (no
	// user-store write, no forward). Additive: events without it decode to "".
	PusherID string `json:"pusher_id"`
	// RepoGroupID is the placement-independent origin of the mirrored upstream:
	// every cell's mirror placement of one upstream carries the same repo_group
	// ULID, resolved by entire-core and stamped onto the event by the entiredb
	// data plane. Empty for native repos and for events predating the field; the
	// ingest origin then falls back to the placement RepoID. Additive: events
	// without it decode to "".
	RepoGroupID string `json:"repo_group_id,omitempty"`
	// OldSymrefTarget/NewSymrefTarget carry a symbolic ref's retargeting for
	// refOpSymrefUpdate events — today only HEAD, emitted by entiredb when a
	// mirror's default branch changes (RepoAdmin.SetDefaultBranch). Full ref
	// names ("refs/heads/main" → "refs/heads/studio"); old is empty when HEAD
	// was previously unborn or detached. Empty on every hash-transition op.
	OldSymrefTarget string `json:"old_symref_target,omitempty"`
	NewSymrefTarget string `json:"new_symref_target,omitempty"`
}

// refOpSymrefUpdate is the ref_op of a symbolic ref retargeting (a HEAD move =
// default-branch change). Such events carry no old/new object targets; the
// transition is OldSymrefTarget → NewSymrefTarget.
const refOpSymrefUpdate = "symref_update"

// wireRefEvent is the on-the-wire envelope: every RefEvent field (promoted via
// embedding so new fields need no copy plumbing) plus the envelope-only Version
// (validated) and HashAlgorithm (unused). Lifted from tlog-viewer/internal/tlog.
type wireRefEvent struct {
	RefEvent
	Version       int    `json:"version"`
	HashAlgorithm string `json:"hash_algorithm"`
}

// ParseRefEvent decodes a NATS message payload into a RefEvent, rejecting
// unknown envelope versions.
func ParseRefEvent(data []byte) (RefEvent, error) {
	var w wireRefEvent
	if err := json.Unmarshal(data, &w); err != nil {
		return RefEvent{}, fmt.Errorf("ingest: decode ref event: %w", err)
	}
	if w.Version != supportedEnvelopeVersion {
		return RefEvent{}, fmt.Errorf("ingest: unsupported envelope version %d", w.Version)
	}
	return w.RefEvent, nil
}
// Package checkpointlayout is the single source of truth for how a checkpoint's
// per-session blobs are addressed in git: the ref they live on, the folder for a
// checkpoint id, the per-session full.jsonl path, and the read cap for one blob.
// Several readers resolve per-session blobs — the transcript endpoints
// (internal/httpapi), checkpoint analysis (internal/analysis), and the
// share-snapshot capture (internal/snapshot) — so the layout is defined here once;
// a drift would otherwise read the wrong bytes. Readers go through
// store.SessionBlobPathAt, which prefers the manifest path hydration stamped
// (session dirs can be sparse) and falls back to this package's
// <folder>/<n>/full.jsonl index layout. It is a leaf package (imports only
// stdlib + oklog/ulid) so every reader can share it without an import cycle.
//
// Two storage backends coexist: the v1 branch uses sharded folders, while the
// ref backend gives each checkpoint a root-tree ref. ULIDs always use refs;
// legacy hex IDs need the persisted ref_backed discriminator because imports
// and migrations may also store them on refs.
//
// The ref format mirrors the CLI's authority
// (cmd/entire/cli/checkpoint/{id/id.go,refs_naming.go} in github.com/entireio/cli);
// keep IsULID / shardFor / RefName / ParseRef in sync with it. layout_test.go
// pins the format.
package checkpointlayout

import (
	"path"
	"strconv"
	"strings"

	ulid "github.com/oklog/ulid/v2"
)

// BranchV1 is the ref a legacy (hex-id) checkpoint's session blobs live on.
const BranchV1 = "entire/checkpoints/v1"

// RefPrefix is the namespace the ref backend stores one ref per checkpoint
// under: refs/entire/checkpoints/<shard>/<id>. Each ref's commit tree root IS the
// checkpoint's contents (metadata.json + per-session dirs), unlike the branch
// backend's sharded folder on BranchV1. Mirrors the CLI's CheckpointRefPrefix.
const RefPrefix = "refs/entire/checkpoints/"

// MaxTranscriptBytes caps a single full.jsonl read. It matches the Repo API's
// 64 MiB decoded CreateCommit payload ceiling so newly published checkpoint
// transcripts can always be consumed in full by strict readers.
const MaxTranscriptBytes = 64 << 20

// IsULID reports whether id is a checkpoint ULID (26-char Crockford base32) in
// canonical form. Mirrors the CLI's id.isULID: ParseStrict enforces the length,
// the Crockford alphabet, and the timestamp-overflow bound; the round-trip
// (v.String() == id) additionally rejects lowercase / Crockford-normalized
// aliases the CLI never emits.
func IsULID(id string) bool {
	v, err := ulid.ParseStrict(id)
	return err == nil && v.String() == id
}

// IsLegacyID reports whether id is the legacy checkpoint shape: exactly 12
// lowercase hexadecimal characters. Imports retain these deterministic IDs when
// stored on the git-refs backend.
func IsLegacyID(id string) bool {
	if len(id) != 12 {
		return false
	}
	for _, c := range id {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// IsCheckpointID accepts the two checkpoint ID formats emitted by the CLI.
func IsCheckpointID(id string) bool {
	return IsLegacyID(id) || IsULID(id)
}

// shardFor is the two-char ref shard for a checkpoint id: its last two chars. A
// ULID's leading chars encode a barely-varying timestamp while its trailing chars
// are random, so suffix-sharding distributes evenly. Mirrors the CLI's
// CheckpointID.ShardFor (which is last-two for all formats).
func shardFor(id string) string {
	if len(id) < 2 {
		return id
	}
	return id[len(id)-2:]
}

// RefName is the per-checkpoint ref for a checkpoint:
// refs/entire/checkpoints/<last2>/<id>. Mirrors the CLI's RefName.
func RefName(id string) string {
	return RefPrefix + shardFor(id) + "/" + id
}

// ParseRef recovers a checkpoint id from a per-checkpoint ref name (RefPrefix +
// exactly <shard>/<id>, shard matching shardFor(id)). The leaf may be a ULID or
// a legacy 12-hex id — `entire import` and the CLI's branch->refs migration
// both file hex-id checkpoints as refs, and the CLI's ParseRef (the authority
// this mirrors) accepts both. Anything else returns ("", false) so the caller
// falls back to branch logic.
func ParseRef(name string) (id string, ok bool) {
	tail, found := strings.CutPrefix(name, RefPrefix)
	if !found {
		return "", false
	}
	shard, rest, cut := strings.Cut(tail, "/")
	// Exactly <shard>/<id>, shard matching the id's own bucket — a ref like
	// <shard>/<id>/0 is not a checkpoint ref.
	if !cut || shard == "" || rest == "" || strings.Contains(rest, "/") {
		return "", false
	}
	if !IsCheckpointID(rest) || shardFor(rest) != shard {
		return "", false
	}
	return rest, true
}

// RefAndFolder maps a checkpoint to the git ref its per-session blobs live on and
// the folder they hang off. A ref-backed checkpoint resolves to its own
// per-checkpoint ref with a root (empty) folder — the ref's commit tree root IS
// the checkpoint; a branch-backed one resolves to the v1 branch with the sharded
// folder id[:2]/id[2:].
//
// refBacked is the stored discriminator (checkpoints.ref_backed, stamped at
// hydrate): a ULID is always ref-backed, but a legacy hex id may be either, so
// id shape alone can't decide. IsULID stays an independent signal so pre-column
// ULID rows (ref_backed defaulting false) still route to their ref; refBacked
// only ever promotes a hex id from the branch to its ref.
func RefAndFolder(checkpointID string, refBacked bool) (ref, folder string) {
	if refBacked || IsULID(checkpointID) {
		return RefName(checkpointID), ""
	}
	folder = checkpointID
	if len(checkpointID) >= 2 {
		folder = checkpointID[:2] + "/" + checkpointID[2:]
	}
	return BranchV1, folder
}

// CheckpointMetaPath is the root metadata.json path for a checkpoint folder,
// tolerating a root (empty) folder — the ref backend's layout — so it yields
// "metadata.json" rather than a leading-slash "/metadata.json".
func CheckpointMetaPath(folder string) string {
	return path.Join(folder, "metadata.json")
}

// SessionBlobPath is the full.jsonl path for session index idx under a folder.
// A root (empty) folder — the ref backend's layout — yields "<idx>/full.jsonl".
func SessionBlobPath(folder string, idx int) string {
	return SessionFilePath(folder, idx, "full.jsonl")
}

// SessionFilePath is the path to a named per-session file (full.jsonl,
// metadata.json, prompt.txt) for session index idx under a folder, tolerating a
// root (empty) folder so the ref backend's root-tree layout produces
// "<idx>/<name>" rather than a leading-slash "/<idx>/<name>".
func SessionFilePath(folder string, idx int, name string) string {
	return path.Join(folder, strconv.Itoa(idx), name)
}
"}

