package ingest

import (
	"context"
	"encoding/json"
	"log/slog"
	"strings"
	"time"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entirehq/entire-api/internal/repoapi"
)

// entireSettingsPath is the repo-relative path of the committed Entire settings
// file the CLI writes. Its checkpoint_remote (when present) names a separate repo
// that stores this repo's checkpoint payload.
const entireSettingsPath = ".entire/settings.json"

// checkpointResolutionKey keys the resolution cache on repo + the ref the
// settings file is read at (the default branch), so a default-branch change
// never serves the old branch's cached outcome.
type checkpointResolutionKey struct{ repoID, ref string }

const (
	// checkpointResolutionCacheSize caps the resolution LRU; sized like
	// repoGroupCacheSize (the working set of repos a busy cell ingests for).
	checkpointResolutionCacheSize = 16384
	// checkpointResolutionTTL bounds staleness for every resolution input: the
	// settings content at the (moving) default branch and the checkpoint repo's
	// mirror status. The resolution is best-effort and re-runs on every push, so
	// a ≤TTL delay in picking up a change is within its existing semantics —
	// while a burst of events on one repo (ENT-1266: 49k identical fetches in
	// ~45min) collapses to one fetch per TTL window.
	checkpointResolutionTTL = 2 * time.Minute
)

// entireSettings is the subset of .entire/settings.json entire-api reads: the
// checkpoint_remote pointer (matches the CLI's CheckpointRemoteConfig and
// entire.io's resolveCheckpointRepo input).
type entireSettings struct {
	StrategyOptions struct {
		CheckpointRemote *struct {
			Provider string `json:"provider"`
			Repo     string `json:"repo"`
		} `json:"checkpoint_remote"`
	} `json:"strategy_options"`
}

// resolveCheckpointRepo reads the code repo's committed .entire/settings.json at
// its default branch and persists repos.checkpoint_repo_id: the Core repo that
// stores this repo's checkpoint payload (entire/checkpoints/v1 branch), or NULL
// when the repo self-hosts. Mirrors entire.io's resolveCheckpointRepo:
//   - no settings file / no checkpoint_remote / unsupported provider → clear (self-hosted)
//   - owner-scoped: the checkpoint repo's owner MUST equal the code repo's owner
//     (fork protection — a fork can't redirect checkpoints into another org)
//   - resolved to a Core ULID via the cell-local github_repo_meta directory
//     (RepoIDByFullName); not mirrored into this cell → clear (not fetchable here)
//
// Best-effort and idempotent: it never fails ingest, and a TRANSIENT read/store
// error leaves the stored value untouched (no flapping). Only a definitive read
// (a parsed settings file, or a clean 404) rewrites the pointer. codeFullName is
// the code repo's "owner/repo" (Core RepoFullName); defaultBranch is the ref the
// settings file is read at.
func (f *Flow) resolveCheckpointRepo(ctx context.Context, rc *repoapi.Client, base, repoID, codeFullName, defaultBranch string) {
	ctx, span := otelsetup.Tracer().Start(ctx, "ingest.resolve_checkpoint_repo",
		trace.WithAttributes(otelsetup.RepoIDAttr(repoID)))
	defer span.End()
	// A burst of ref events on one repo must not become a 1:1 settings-fetch
	// storm against the Repo API (ENT-1266: 49k identical fetches — all 404s —
	// in ~45min while the default branch never moved). A cached definitive
	// outcome, INCLUDING the negative "no settings file" one, short-circuits the
	// whole resolution: the fetch, the directory lookup, and the (idempotent)
	// pointer write it would repeat.
	key := checkpointResolutionKey{repoID: repoID, ref: defaultBranch}
	if outcome, ok := f.checkpointResolutions.get(key); ok {
		span.SetAttributes(
			attribute.String("entire.checkpoint_resolution_outcome", outcome),
			attribute.Bool("entire.checkpoint_resolution_cached", true))
		return
	}
	// The resolution is otherwise silent — a 404 self-hosts, a transient read only
	// WarnContexts — which made a fleet-wide read failure (e.g. a degraded raw-file
	// endpoint) invisible. Record the outcome so the distribution is queryable
	// (break down by entire.checkpoint_resolution_outcome). Side effects are
	// unchanged. Key uses the entire. namespace, like the other custom span attrs.
	outcome := f.resolveCheckpointRepoOutcome(ctx, rc, base, repoID, codeFullName, defaultBranch)
	if checkpointOutcomeDefinitive(outcome) {
		f.checkpointResolutions.put(key, outcome, checkpointResolutionTTL)
	}
	span.SetAttributes(attribute.String("entire.checkpoint_resolution_outcome", outcome))
}

// checkpointOutcomeDefinitive reports whether an outcome label is a stable fact
// of the settings file at the resolved ref (cacheable for a TTL) rather than a
// transient/incomplete input that must retry on the next event. parse_error is
// deliberately transient: the no-clobber comment in the parse branch treats a
// blip as possible, so caching it would pin a blip for a full TTL.
func checkpointOutcomeDefinitive(outcome string) bool {
	switch outcome {
	case "self_hosted_no_settings", "self_hosted_no_remote", "owner_mismatch",
		"not_mirrored", "resolved", "remote_unsupported":
		return true
	}
	return false
}

// resolveCheckpointRepoOutcome runs the resolution and returns a short outcome
// label for telemetry. Outcomes: no_default_branch, ctx_cancelled,
// self_hosted_no_settings (file not found), read_error (transient), parse_error,
// self_hosted_no_remote, remote_unsupported (transient), owner_unknown
// (transient), owner_mismatch, resolve_error (transient), persist_error
// (transient: the pointer write failed), not_mirrored, resolved.
// Only the two definitive self-hosted signals (no settings file, no
// checkpoint_remote) and owner_mismatch clear the pointer; resolved sets it; every
// other outcome leaves it untouched (incomplete/transient input is never a reason
// to drop a good association). An outcome that writes the pointer holds only if
// the write landed — a failed persist downgrades it to persist_error so the next
// event retries instead of the caller caching a state the store never reached.
func (f *Flow) resolveCheckpointRepoOutcome(ctx context.Context, rc *repoapi.Client, base, repoID, codeFullName, defaultBranch string) string {
	if defaultBranch == "" {
		return "no_default_branch" // no branch to read settings from
	}
	if err := f.waitRepoAPI(ctx); err != nil {
		return "ctx_cancelled" // best-effort, leave unchanged
	}
	// Probe via the /files batch read, NOT GET /raw: most repos have no
	// settings file, and raw's 404 for that expected outcome marks the client
	// and server spans as errors — during a busy repo's event burst those benign
