// resolveCheckpoint locates one checkpoint and returns entire.io's resolve
// envelope: the fully-composed checkpoint plus its branch membership and the
// redirect decision for the branch the caller was viewing. It mirrors entire.io's
// /checkpoints/resolve/:checkpointId handler (cache.ts) — the same locator the web
// BFF proxies this detail endpoint for.
func resolveCheckpoint(ctx context.Context, deps *RepoActivityDeps, in *CheckpointResolveInput) (*CheckpointResolveOutput, error) {
	// entire.io rejects a malformed branch up front (the param only steers the
	// redirect decision, but a bad value is still a client error).
	if in.Branch != "" && !isValidBranchName(in.Branch) {
		return nil, huma.Error400BadRequest("invalid branch name format")
	}

	// The checkpoint payload lives under the checkpoint-storage repo (identity when
	// self-hosted); the links stay under the code repo (in.RepoID).
	storageRepoID, err := deps.checkpointStorageRepoID(ctx, in.RepoID)
	if err != nil {
		return nil, err
	}
	cp, ok, err := deps.Store.GetCheckpointComposed(ctx, in.RepoID, storageRepoID, in.CheckpointID)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: checkpoint", err)
	}
	if !ok {
		return nil, huma.Error404NotFound("checkpoint not found")
	}

	meta, _, err := deps.Store.GetRepoMeta(ctx, in.RepoID)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: repo meta", err)
	}

	composed, err := composeCheckpointDetail(ctx, deps, in.RepoID, storageRepoID, repoFullNameOr(meta, in.RepoID), []store.CheckpointWithCommit{cp})
	if err != nil {
		return nil, huma.Error500InternalServerError("store: resolved session names", err)
	}
	checkpoint := composed[0]

	// Branch classification. entiredb returns reachability booleans only (no branch
	// names), so branches degrade to default-branch-only: [default] when the
	// checkpoint's anchor commit is reachable from the default branch, [] otherwise.
	// Best-effort like entire.io and the commit resolver — an unconfigured repo API
	// or a membership failure degrades to "no branches", not a 5xx, since the
	// checkpoint already resolved. Keyed on the composed anchor SHA.
	//
	// The default-branch name is resolved with the shared "main" fallback (matching
	// entire.io's findById default) so an unpopulated repo-meta default_branch still
	// labels an on-default checkpoint — otherwise ?branch=main would falsely redirect.
	defaultBranch := store.ResolveBranchName("", meta.DefaultBranch)

