	huma.Register(api, publicOp("repoOverviewCheckpointMetrics", http.MethodGet, "/repos/{repo_id}/overview/checkpoint-metrics",
		"Average per-checkpoint metrics on the default branch", "overview"),
		func(ctx context.Context, in *RepoCheckpointMetricsInput) (*RepoCheckpointMetricsOutput, error) {
			meta, _, err := deps.Store.GetRepoMeta(ctx, in.RepoID)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: repo meta", err)
			}
			since, sinceEcho := parseOverviewDate(in.Since)
			until, untilEcho := parseOverviewDate(in.Until)
			// Metric averages read the checkpoint payload under the storage repo (see
			// agent-activity); resolve + gate it so an external checkpoints repo isn't
			// read as empty.
			storageRepoID, err := resolveCheckpointStorage(ctx, deps, in.RepoID)
			if err != nil {
				return nil, err
			}
			m, err := deps.Store.CheckpointMetrics(ctx, in.RepoID, storageRepoID, since, until)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: checkpoint metrics", err)
			}
			out := &RepoCheckpointMetricsOutput{}
			out.Body.CheckpointCount = m.CheckpointCount
			out.Body.AvgTokensPerCheckpoint = m.AvgTokensPerCheckpoint
			out.Body.AvgSessionsPerCheckpoint = m.AvgSessionsPerCheckpoint
			out.Body.TotalMessages = m.TotalMessages
			out.Body.AvgMessagesPerCheckpoint = m.AvgMessagesPerCheckpoint
			out.Body.TokensPerMessage = m.TokensPerMessage
			out.Body.Branch = store.ResolveBranchName("", meta.DefaultBranch)
			out.Body.Since, out.Body.Until = sinceEcho, untilEcho
			return out, nil
		})

	registerRepoTLDR(api, deps, publicCheckpointOp)

	huma.Register(api, publicOp("repoOverviewAgentActivity", http.MethodGet, "/repos/{repo_id}/overview/agent-activity",
		"Daily per-agent checkpoint activity on the default branch", "overview"),
		func(ctx context.Context, in *RepoAgentActivityInput) (*RepoAgentActivityOutput, error) {
			meta, _, err := deps.Store.GetRepoMeta(ctx, in.RepoID)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: repo meta", err)
			}
			since, sinceEcho := parseOverviewDate(in.Since)
			until, untilEcho := parseOverviewDate(in.Until)
			// Checkpoint payload (agent, tokens) lives under the checkpoint storage repo
			// — the code repo itself when self-hosted, a separate repo for a configured
			// checkpoint_remote — while the commit links live under the code repo. Resolve
			// (and gate) the storage repo so the panel reads the right one; without this a
			// repo with an external checkpoints repo returns an empty panel.
			storageRepoID, err := resolveCheckpointStorage(ctx, deps, in.RepoID)
			if err != nil {
				return nil, err
			}
			daily, err := deps.Store.AgentActivity(ctx, in.RepoID, storageRepoID, since, until)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: agent activity", err)
			}
			out := &RepoAgentActivityOutput{}
			out.Body.Daily = agentActivityDayItems(daily)
			out.Body.Branch = store.ResolveBranchName("", meta.DefaultBranch)
			out.Body.Since, out.Body.Until = sinceEcho, untilEcho
			return out, nil
		})

