package httpapi

import (
	"context"
	"errors"
	"net/http"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entiredb/modules/authz"

	"github.com/entirehq/entire-api/internal/auth"
	"github.com/entirehq/entire-api/internal/coreapi"
	"github.com/entirehq/entire-api/internal/reposettings"
	"github.com/entirehq/entire-api/internal/store"
)

// teamOp builds a repo- or project-scoped operation. tag is the OpenAPI tag the
// route is grouped under (its resource, e.g. "repos" / "sessions" / "code"), kept
// independent of the access gate mw so grouping tracks the resource, not the
// middleware bundle. Prefer repoOp / projectOp (registerRepos / registerProjects),
// which bundle the access gate so a scoped route cannot be registered ungated.
func teamOp(api huma.API, id, method, path, summary, tag string, mw []opMiddleware) huma.Operation {
	return huma.Operation{OperationID: id, Method: method, Path: apiPrefix + path, Summary: summary,
		Description: opDescriptions[id],
		Tags:        []string{tag}, Security: secSchemesFor(api), Errors: stdErrors, Middlewares: mw}
}

// registerRepos wires the repo-scoped aggregate + list endpoints. repoOp bundles
// the access gate (authn + requireRepoAccess), so every handler registered
// through repoOp or repoWriteOp runs only for a caller authorized on {repo_id} —
// those handlers carry no authz prefix.
func registerRepos(api huma.API, deps *RepoActivityDeps) {
	gate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireRepoAccess(api, deps)}
	repoOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, gate)
	}
	// Write operations gate on repo push (not pull): a rename mutates product
	// state, so it needs more than read access.
	writeGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireRepoPush(api, deps)}
	repoWriteOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, writeGate)
	}
	// Repo-admin (manage_settings) tier: for the handful of repos.go writes that
	// flip a repo-wide gate-enforcement toggle rather than an ordinary product
	// preference — same tier the trails gate-settings/gate-definition admin
	// routes already require (trails_gate_settings.go), not merely push.
	manageSettingsGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireRepoManageSettings(api, deps)}
	repoManageSettingsOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, manageSettingsGate)
	}
	// Bulk-id hydration has no {repo_id} to gate on, so it carries only
	// requireAuth and does its own fail-closed per-id access check in the
	// handler (repoMetadataAccess: repo/view_metadata, not repo/pull).
	listGate := []opMiddleware{requireAuth(api, &deps.baseDeps)}
	listOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, listGate)
	}
	// Public-repo reads: accepts both authenticated users and anonymous readers
	// (X-Anon-Repo header). anonOrRequireAuth handles both flows in one
	// middleware — anonymous requests check SpiceDB public_viewer then mint a
	// scoped JWT; authenticated requests run the normal requireAuth +
	// requireRepoAccess chain. Read-only: write operations stay on writeGate.
	publicGate := []opMiddleware{anonOrRequireAuth(api, deps)}
	publicOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, publicGate)
	}
	// Checkpoint-data endpoints (prompts / session metadata / analysis) gate
	// additionally on the storage repo's ACL when checkpoints live in a separate
	// repo (see requireCheckpointDataAccess). The ACL runs with the request's
	// identity — for an anonymous caller that is the synthetic __anon__ account,
	// so a separate storage repo is only readable when it is itself public
	// (account:* pull); otherwise the route hard-denies 404. Transcripts run the
	// same resolve+gate in-handler — they need the resolved storage repo id to
	// read content from — so they stay on publicOp. (Copy gate before appending
	// so the base slice is unshared.)
	publicCheckpointGate := append(append([]opMiddleware{}, publicGate...), requireCheckpointDataAccess(api, deps))
	publicCheckpointOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, publicCheckpointGate)
	}
	// Authenticated twin of publicCheckpointOp: same checkpoint-data ACL,
	// minus the anonymous public-repo flow — for checkpoint-data reads on
	// surfaces that always carry a bearer (the search hydration path).
	authedCheckpointGate := append(append([]opMiddleware{}, gate...), requireCheckpointDataAccess(api, deps))
	authedCheckpointOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, authedCheckpointGate)
	}
	// The shared-session transcript read: a member with a token reads live
	// through entiredb (the gate runs in the handler); an anonymous caller with
	// X-Anon-Repo runs the public-repo flow (public repos read live like
	// members); an anonymous caller WITHOUT the header is served the encrypted
	// snapshot when a share row exists, else 404 — share links on private repos
	// are unchanged.
	anonOptionalGate := []opMiddleware{anonOrOptionalAuth(api, deps)}
	anonOptionalOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, anonOptionalGate)
	}
	// Anonymous surface (anon-public-repo-reads Phase 3, decided 2026-07-02):
	// every repo-scoped GET is anonymous-capable on public repos EXCEPT the raw
	// transcript variants (held back until non-raw redaction is proven) — those
	// stay on repoOp. Writes stay authenticated.

	// Explicit-id hydration is authenticated, but does
	// not enumerate membership. The handler bulk-checks repo/view_metadata for
	// every requested id, silently drops denied ids, and resolves access facts for
	// the survivors before touching the store.
	huma.Register(api, listOp("batchRepos", http.MethodPost, "/repos/batch",
		"Hydrate repositories by id", "repos"),
		func(ctx context.Context, in *ReposBatchInput) (*ReposListOutput, error) {
			ids, access, err := repoMetadataAccess(ctx, deps.Reader, in.Body.IDs)
			if err != nil {
				return nil, err
			}
			deps.devElevateReportedAccess(access)
			rows, err := deps.Store.ListRepoMetas(ctx, ids)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: batch repos", err)
			}
			now := time.Now().UTC()
			var activity map[string][]int
			if slices.Contains(in.Body.Include, "activity") {
				activity, err = deps.Store.WeeklyActivity(ctx, ids, activityWeeks, now)
				if err != nil {
					return nil, huma.Error500InternalServerError("store: repo activity", err)
				}
			}
			out := &ReposListOutput{}
			out.Body.Repos = repoListItems(rows, access, activity)
			out.Body.UpdatedAt, out.Body.FromDB = isoTime(now), true
			return out, nil
		})

	// Single-repo meta: the repo list item shape for one repo. publicOp so an
	// anonymous public-repo viewer can render the repo header (display name,
	// stars, default branch) without authenticating. The caller's tier is
	// resolved by point checks — pull is guaranteed by the gate, and the
	// anonymous wildcard never holds push/manage, so anonymous callers always
	// read as "read".
	huma.Register(api, publicOp("repoMeta", http.MethodGet, "/repos/{repo_id}",
		"Metadata for one repository", "repos"),
		func(ctx context.Context, in *RepoMetaInput) (*RepoMetaOutput, error) {
			rows, err := deps.listRepoMetasCompared(ctx, []string{in.RepoID})
			if err != nil {
				return nil, humaOr500(err, "store: repo meta")
			}
			if len(rows) == 0 {
				return nil, huma.Error404NotFound("repo not found")
			}
			ac, err := perRequestAccessChecker(ctx, deps.Reader)
			if err != nil {
				return nil, huma.Error500InternalServerError("auth: access checker", err)
			}
			// info defaults to the anonymous shape: read tier, read data role, no
			// management. The anonymous wildcard never holds push/manage/
			// manage_settings — skip the point checks on the anonymous hot path
			// (this endpoint renders every anonymous repo header) rather than
			// asking SpiceDB questions with a known answer. can_manage_access is
			// derived by repoListItem (HoldsManage && !is_mirror).
			info := auth.RepoAccess{Tier: auth.RepoTierRead, DataRole: auth.RepoTierRead}
			if !ac.Identity().IsAnon() {
				hasPush, err := ac.HasPermission(ctx, "repo", in.RepoID, string(authz.Push))
				if err != nil {
					return nil, huma.Error503ServiceUnavailable("core: access check", err)
				}
				hasManageSettings, err := ac.HasPermission(ctx, "repo", in.RepoID, string(authz.ManageSettings))
				if err != nil {
					return nil, huma.Error503ServiceUnavailable("core: access check", err)
				}
				hasManage, err := ac.HasPermission(ctx, "repo", in.RepoID, string(authz.Manage))
				if err != nil {
					return nil, huma.Error503ServiceUnavailable("core: access check", err)
				}
				if hasPush {
					info.DataRole = auth.RepoTierWrite
					info.Tier = auth.RepoTierWrite
				}
				if hasManageSettings {
					info.Tier = auth.RepoTierAdmin
				}
				info.CanManageSettings = hasManageSettings
				info.HoldsManage = hasManage
				// Inside the non-anon branch: this route is public, and an
				// anonymous viewer holds none of these for real. The list routes
				// elevate a member set, which is empty for anonymous callers.
				info = deps.devElevateRepoAccess(info)
			}
			item := repoListItem(rows[0], info)
			// The product toggles are member configuration, not public display
			// data — zero them for anonymous callers (decided 2026-07-02). The
			// wire shape stays identical; only the values collapse.
			if ac.Identity().IsAnon() {
				item.RunnersEnabled = false
				item.TrailsEnabled = false
				item.AutoRunOnPush = false
				item.PublicSharingEnabled = false
			}
