	publicCheckpointGate := append(append([]opMiddleware{}, publicGate...), requireCheckpointDataAccess(api, deps))
	publicCheckpointOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, publicCheckpointGate)
	}
	// Authenticated twin of publicCheckpointOp: same checkpoint-data ACL,
	// minus the anonymous public-repo flow — for checkpoint-data reads on
	// surfaces that always carry a bearer (the search hydration path).
	authedCheckpointGate := append(append([]opMiddleware{}, gate...), requireCheckpointDataAccess(api, deps))
	authedCheckpointOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, authedCheckpointGate)
	}
