	// through entiredb (the gate runs in the handler); an anonymous caller with
	// X-Anon-Repo runs the public-repo flow (public repos read live like
	// members); an anonymous caller WITHOUT the header is served the encrypted
	// snapshot when a share row exists, else 404 — share links on private repos
	// are unchanged.
	anonOptionalGate := []opMiddleware{anonOrOptionalAuth(api, deps)}
	anonOptionalOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, anonOptionalGate)
	}
	// Anonymous surface (anon-public-repo-reads Phase 3, decided 2026-07-02):
	// every repo-scoped GET is anonymous-capable on public repos EXCEPT the raw
	// transcript variants (held back until non-raw redaction is proven) — those
	// stay on repoOp. Writes stay authenticated.

	// Explicit-id hydration is authenticated, but does
	// not enumerate membership. The handler bulk-checks repo/view_metadata for
	// every requested id, silently drops denied ids, and resolves access facts for
	// the survivors before touching the store.
	huma.Register(api, listOp("batchRepos", http.MethodPost, "/repos/batch",
		"Hydrate repositories by id", "repos"),
		func(ctx context.Context, in *ReposBatchInput) (*ReposListOutput, error) {
			ids, access, err := repoMetadataAccess(ctx, deps.Reader, in.Body.IDs)
			if err != nil {
				return nil, err
			}
			deps.devElevateReportedAccess(access)
			rows, err := deps.Store.ListRepoMetas(ctx, ids)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: batch repos", err)
			}
			now := time.Now().UTC()
			var activity map[string][]int
			if slices.Contains(in.Body.Include, "activity") {
				activity, err = deps.Store.WeeklyActivity(ctx, ids, activityWeeks, now)
				if err != nil {
					return nil, huma.Error500InternalServerError("store: repo activity", err)
				}
			}
			out := &ReposListOutput{}
