	// anonymous public-repo viewer can render the repo header (display name,
	// stars, default branch) without authenticating. The caller's tier is
	// resolved by point checks — pull is guaranteed by the gate, and the
	// anonymous wildcard never holds push/manage, so anonymous callers always
	// read as "read".
	huma.Register(api, publicOp("repoMeta", http.MethodGet, "/repos/{repo_id}",
		"Metadata for one repository", "repos"),
		func(ctx context.Context, in *RepoMetaInput) (*RepoMetaOutput, error) {
			rows, err := deps.listRepoMetasCompared(ctx, []string{in.RepoID})
			if err != nil {
				return nil, humaOr500(err, "store: repo meta")
			}
			if len(rows) == 0 {
				return nil, huma.Error404NotFound("repo not found")
			}
			ac, err := perRequestAccessChecker(ctx, deps.Reader)
			if err != nil {
				return nil, huma.Error500InternalServerError("auth: access checker", err)
			}
			// info defaults to the anonymous shape: read tier, read data role, no
			// management. The anonymous wildcard never holds push/manage/
			// manage_settings — skip the point checks on the anonymous hot path
			// (this endpoint renders every anonymous repo header) rather than
			// asking SpiceDB questions with a known answer. can_manage_access is
			// derived by repoListItem (HoldsManage && !is_mirror).
			info := auth.RepoAccess{Tier: auth.RepoTierRead, DataRole: auth.RepoTierRead}
			if !ac.Identity().IsAnon() {
				hasPush, err := ac.HasPermission(ctx, "repo", in.RepoID, string(authz.Push))
				if err != nil {
					return nil, huma.Error503ServiceUnavailable("core: access check", err)
				}
				hasManageSettings, err := ac.HasPermission(ctx, "repo", in.RepoID, string(authz.ManageSettings))
				if err != nil {
					return nil, huma.Error503ServiceUnavailable("core: access check", err)
				}
				hasManage, err := ac.HasPermission(ctx, "repo", in.RepoID, string(authz.Manage))
				if err != nil {
					return nil, huma.Error503ServiceUnavailable("core: access check", err)
				}
				if hasPush {
					info.DataRole = auth.RepoTierWrite
					info.Tier = auth.RepoTierWrite
				}
				if hasManageSettings {
					info.Tier = auth.RepoTierAdmin
				}
				info.CanManageSettings = hasManageSettings
				info.HoldsManage = hasManage
