				// anonymous viewer holds none of these for real. The list routes
				// elevate a member set, which is empty for anonymous callers.
				info = deps.devElevateRepoAccess(info)
			}
			item := repoListItem(rows[0], info)
			// The product toggles are member configuration, not public display
			// data — zero them for anonymous callers (decided 2026-07-02). The
			// wire shape stays identical; only the values collapse.
			if ac.Identity().IsAnon() {
				item.RunnersEnabled = false
				item.TrailsEnabled = false
				item.AutoRunOnPush = false
				item.PublicSharingEnabled = false
			}
