package proxy

import (
	"context"
	"log/slog"
	"net/http"
	"net/url"
)

// CheckpointStorageResolver is the search-route analogue of httpapi's
// per-handler checkpointStorageRepoID resolution (ENT-1654): callers name the
// CODE repo, and entire-api transparently answers from wherever that repo's
// checkpoints actually live. Search documents are namespaced by the repo the
// checkpoint refs were pushed to — the storage repo when a checkpoint_remote
// is configured — so a filter naming only the code repo would search an
// empty namespace and return a confident zero.
//
// The resolution deliberately lives HERE, in the checkpoint system of
// record, and not in the search service or its callers: whether a repo
// stores its checkpoints remotely is not search's problem. The gateway is
// also the one choke point every search caller traverses (the BFF's per-cell
// fan-out and the CLI's direct call), so the ?repo= filter is widened with
// each repo's storage ULID on an explicit allowlist of the search upstream's
// operations, before the request leaves this process.
//
// Authorization is unchanged: the search service resolves every repo id
// against the caller's own accessible set and silently drops the rest, so an
// appended storage repo the caller cannot read is never searched. The
// mapping itself is not a disclosure — a repo's checkpoint_remote is public
// in its committed .entire/settings.json (see httpapi's checkpoint-status).
type CheckpointStorageResolver struct {
	Upstream string
	// Routes is the explicit allowlist of merged-document paths (the OpenAPI
	// path keys BuildRouter routes on, e.g. "/semantic-search/search/v1/search")
	// the expansion applies to. Scoping is per-operation, not per-upstream, so
	// a new operation in the upstream's spec never silently inherits it.
	// Empty = the expansion applies nowhere.
	Routes []string
	// Resolve maps code repo ULIDs to their checkpoint-storage repo ULIDs
	// (identity when self-hosted). A nil Resolve, a lookup error, or a
	// missing entry leaves the filter unexpanded — the search then behaves
	// exactly as before this gate existed.
	Resolve func(ctx context.Context, repoIDs []string) (map[string]string, error)
}

// maxStorageResolveRepos bounds the store lookup: a filter larger than any legitimate
// caller sends (the BFF caps its own inputs at 100) proxies through
// unexpanded rather than building an oversized ANY($1) query from
// caller-controlled input. The upstream then enforces its own filter limits.
const maxStorageResolveRepos = 100

// wrap widens the request's ?repo= values with their storage repos before
// handing off to next. The request is shallow-cloned (as http.StripPrefix
// does) so the rewritten query never escapes to other handlers; requests
// without a repo filter pass through untouched, preserving the unfiltered
// search's "cell scopes by token" contract.
func (g *CheckpointStorageResolver) wrap(next http.Handler, log *slog.Logger) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		repos := r.URL.Query()["repo"]
		if len(repos) == 0 || len(repos) > maxStorageResolveRepos || g.Resolve == nil {
			next.ServeHTTP(w, r)
			return
		}
		resolved, err := g.Resolve(r.Context(), repos)
		if err != nil {
			// Best-effort: without the mapping the search still runs against
			// the requested repos, which is exactly the pre-gate behavior.
			log.WarnContext(r.Context(), "checkpoint storage resolve failed",
				slog.String("path", r.URL.Path),
				slog.String("error", err.Error()),
			)
			next.ServeHTTP(w, r)
			return
		}
		seen := make(map[string]struct{}, len(repos))
		for _, id := range repos {
			seen[id] = struct{}{}
		}
		var extras []string
		for _, id := range repos {
			storage := resolved[id]
			if storage == "" || storage == id {
				continue
			}
			if _, ok := seen[storage]; ok {
				continue
			}
			seen[storage] = struct{}{}
			extras = append(extras, storage)
		}
		if len(extras) == 0 {
			next.ServeHTTP(w, r)
			return
		}
		q := r.URL.Query()
		for _, storage := range extras {
			q.Add("repo", storage)
		}
		r2 := new(http.Request)
		*r2 = *r
		r2.URL = new(url.URL)
		*r2.URL = *r.URL
		r2.URL.RawQuery = q.Encode()
		next.ServeHTTP(w, r2)
	})
}

