// --- parsed handlers --------------------------------------------------

// resolveCheckpointStorage maps a code repo to the repo that actually stores its
// checkpoint payload (the entire/checkpoints/v1 branch + the checkpoint/session
// rows). The code repo carries the commit links and the read envelope; the
// storage repo carries the checkpoint rows and the full.jsonl blobs. They are the
// same repo today (CheckpointStorageRepoID is identity until the association is
// populated), so the gate below never triggers; it encodes the happy-path access
// contract for when they diverge.
//
// Contract: a checkpoint is only fetchable if the caller can read BOTH the code
// repo (already gated by the route's pull check) AND the storage repo. When the
// two differ we add the storage-repo read check here — an access-check error is a
// service problem (503, matching checkRepoPermission); a deny surfaces as 404 (the
// same not-found shape the rest of the file uses) so we don't leak that the code
// repo's checkpoints are stored in a repo the caller can't see.

// checkpointStorageRepoID resolves the repo whose entire/checkpoints/v1 branch
// holds codeRepoID's checkpoint payload and session rollup — codeRepoID itself
// when self-hosted, a separate repo for a configured checkpoint_remote — mapping
// a store failure to a 500. This is the non-gated resolve used by session-table
// reads (already gated on the code repo by their route). resolveCheckpointStorage
// is the gated companion that additionally runs the storage-repo ACL check.
func (deps *RepoActivityDeps) checkpointStorageRepoID(ctx context.Context, codeRepoID string) (string, error) {
	storageRepoID, err := deps.Store.CheckpointStorageRepoID(ctx, codeRepoID)
	if err != nil {
		return "", huma.Error500InternalServerError("store: checkpoint storage repo", err)
	}
	return storageRepoID, nil
}

// checkpointStorageAccess resolves the checkpoint-storage repo and reports whether
// the caller may see its checkpoint data (prompts, session titles). It is the
// redaction companion to resolveCheckpointStorage: where the checkpoint-data routes
// hard-deny (404) via requireCheckpointDataAccess, the preview-embedding routes
// (commits list / commit detail / compare) gate only on the code repo, so a
// code-repo-only reader must be shown commits WITHOUT the storage repo's checkpoint
// previews rather than denied. When storage == code (self-hosted, the common case)
// the route's own code-repo gate already authorized it → canSee=true with no extra
// Core call. When storage is a separate repo, canSee requires pull on it; a miss
// returns canSee=false (redact) rather than an error. Store/authz failures surface
// as 500/503.
func (deps *RepoActivityDeps) checkpointStorageAccess(ctx context.Context, codeRepoID string) (storageRepoID string, canSee bool, err error) {
	storageRepoID, err = deps.checkpointStorageRepoID(ctx, codeRepoID)
	if err != nil {
		return "", false, err
	}
	if storageRepoID == codeRepoID {
		return storageRepoID, true, nil
	}
	ac, err := perRequestAccessChecker(ctx, deps.Reader)
	if err != nil {
		return "", false, huma.Error500InternalServerError("authz: access checker", err)
	}
	allowed, err := ac.HasPermission(ctx, "repo", storageRepoID, permRepoRead)
	if err != nil {
		return "", false, huma.Error503ServiceUnavailable("core: access check", err)
	}
	return storageRepoID, allowed, nil
}

// resolveCheckpointStorage is the hard-deny adapter over checkpointStorageAccess:
// the checkpoint-data routes (dedicated /checkpoints, transcripts) can't redact, so
// a caller without read on a separate storage repo gets 404 (don't leak that the
// checkpoints live elsewhere) rather than the preview routes' empty-list redaction.
func resolveCheckpointStorage(ctx context.Context, deps *RepoActivityDeps, codeRepoID string) (string, error) {
	storageRepoID, canSee, err := deps.checkpointStorageAccess(ctx, codeRepoID)
	if err != nil {
		return "", err
	}
	if !canSee {
		return "", huma.Error404NotFound("checkpoint not found")
	}
	return storageRepoID, nil
}

// checkpointPayloadVisible reports whether the caller may read the code repo's
// checkpoint payload: true when self-hosted (storage == code, already authorized by
// the route's code-repo gate) or when the caller has read on the SEPARATE storage
// repo. It is the redaction companion for the scope-based activity readers (Summary /
// ActivityBuckets / Contributors / Agents / CheckpointAgents): a false result redacts
// the storage-repo-derived stats via scope.RedactCheckpointPayload rather than
// hard-denying, so the commit axis (code-repo data the caller can see) still renders.
// Mirrors checkpointStorageAccess's canSee, dropping the resolved id — the scope
// readers resolve code→storage in SQL themselves.
func (deps *RepoActivityDeps) checkpointPayloadVisible(ctx context.Context, codeRepoID string) (bool, error) {
	_, canSee, err := deps.checkpointStorageAccess(ctx, codeRepoID)
	return canSee, err
}

// storageReadContext returns a context whose forwarded bearer authorizes the
// entiredb read against the checkpoint-storage repo.
//
// The anon middleware mints a scoped JWT for the CODE repo (the X-Anon-Repo / URL
// repo). entiredb authorizes a scoped token OFFLINE against the single repo it is
// scoped to (its aud + repo_id, both derived from the minted repo — see
// auth.AnonSigner.Mint), so when the checkpoint blobs live under a SEPARATE storage
// repo the code-scoped token is rejected on every blob read. Re-mint a
// storage-scoped anon token for that hop.
//
// SECURITY: entiredb does NOT SpiceDB-check a scoped token — it trusts the repo the
// token is scoped to. So this MUST be called only after the anon caller's read of
// storageRepoID has been authorized in entire-api (callerRepoReadAccess /
// resolveCheckpointStorage, which for the __anon__ account passes only on a
// public_viewer storage repo). Minting upstream of that gate would hand an anon
// caller a token for a repo it can't read — turning a crafted checkpoint_remote
// into a read oracle for private repos. Keep the mint inside the gated branch.
//
// Any non-anon caller (a member — or, defensively, a caller with no attached
// identity) forwards its bearer unchanged; entiredb authorizes a member's identity
// token live against SpiceDB, honouring whatever grants the storage repo actually
// carries. Self-hosted (storage == code, the common case) is a no-op.
func (deps *RepoActivityDeps) storageReadContext(ctx context.Context, codeRepoID, storageRepoID string) (context.Context, error) {
	if storageRepoID == codeRepoID {
		return ctx, nil
	}
	id := auth.FromContext(ctx)
	if id == nil || !id.IsAnon() {
		return ctx, nil
	}
	if deps.AnonSigner == nil {
		return nil, huma.Error500InternalServerError("anon: signer not configured", errors.New("AnonSigner nil"))
			return
		}
		next(hctx)
	}
}

// requireCheckpointDataAccess is the second half of the checkpoint-data access
// contract (see resolveCheckpointStorage). The route already gated the caller on
// {repo_id} (the code repo) via requireRepoAccess; this additionally requires
// read access to the repo that actually stores the checkpoint payload (prompts,
// session metadata, transcripts) when that's a different repo. Without it, a
// caller who can read the code repo but not the (stricter) checkpoint repo would
// see checkpoint data the checkpoint repo's ACL is meant to withhold. A deny
// renders as 404 (don't leak that the code repo's checkpoints live in a repo the
// caller can't see); an access-check error as 503. A no-op when storage repo ==
// code repo (every self-hosted repo, and until checkpoint_repo_id is populated).
func requireCheckpointDataAccess(api huma.API, deps *RepoActivityDeps) opMiddleware {
	return func(hctx huma.Context, next func(huma.Context)) {
		storageRepoID, err := resolveCheckpointStorage(hctx.Context(), deps, hctx.Param("repo_id"))
		if err != nil {
			writeAccessErr(api, hctx, err)
			return
		}
		// Stash the resolved (and ACL-checked) storage id so the handler
		// doesn't repeat the repos point query (see storageRepoIDFromContext).
		next(huma.WithValue(hctx, storageRepoIDKey{}, storageRepoID))
	}
}

type storageRepoIDKey struct{}

// storageRepoIDFromContext returns the checkpoint-storage repo id
// requireCheckpointDataAccess resolved for this request, falling back to the
// (ungated) point query for handlers reached through other gates.
func storageRepoIDFromContext(ctx context.Context, deps *RepoActivityDeps, codeRepoID string) (string, error) {
	if sid, ok := ctx.Value(storageRepoIDKey{}).(string); ok && sid != "" {
		return sid, nil
	}
	return deps.checkpointStorageRepoID(ctx, codeRepoID)
}

// callerCacheKey resolves a caller-scoped string for a per-caller cache key
// (the SSE re-auth caches keyed per viewer) — never for attribution or
// storage. An account subject returns its bare account id; an automation
// returns its own subject id (aut_<ulid>), distinct and stable per
// automation, so per-caller caching stays correctly scoped rather than
// collapsing every automation onto one empty-string key.
func callerCacheKey(ctx context.Context) string {
	return auth.BareID(ctx)
}

// requireAccountSubject refuses any caller whose Identity isn't an account
// subject (a bare-ULID human or svc_<ulid> service account) — for routes that
// read or write rows keyed by the caller's own account id (the personal /me
// surfaces, user/repo preferences) where an automation principal has no
// meaningful identity to key on. Must run after requireAuth, which attaches
// membership join: the caller resolves reachability from entiredb and passes the
// SHA set here to intersect with the local checkpoint links. (Limit-only, matching
// entire.io — no cursor on this list.)
//
// The link→payload join spans two repos: checkpoint_commits rows live under the
// CODE repo (codeRepoID, where the anchoring commits landed — see indexCommitData),
// while the checkpoints payload lives under the STORAGE repo (storageRepoID, the
// repo whose entire/checkpoints/v1 branch was hydrated — see hydrateCheckpoint).
// They differ only when the code repo configures a checkpoint_remote; for a
// self-hosted repo pass storageRepoID == codeRepoID (see CheckpointStorageRepoID),
// which restores the single-repo behaviour byte-for-byte.
// since/until optionally bound the sel CTE to commits whose commit_date falls in
// [since, until) — nil means unbounded on that side. Either or both may be nil;
// most callers (single-commit or full-branch checkpoint previews with no time
// window concept) pass nil, nil, which keeps the query text byte-identical to
// the unfiltered form.
func (s *RepoStore) ListCheckpointsForCommits(ctx context.Context, codeRepoID, storageRepoID string, shas []string, since, until *time.Time, limit int) ([]CheckpointWithCommit, error) {
	if limit <= 0 || limit > 1000 {
		limit = 100
	}
	if len(shas) == 0 {
		return nil, nil
	}
	codeRid, err := ulidBytes(codeRepoID)
	if err != nil {
		return nil, fmt.Errorf("store: list checkpoints for commits %s: %w", codeRepoID, err)
	}
	storageRid, err := ulidBytes(storageRepoID)
	if err != nil {
		return nil, fmt.Errorf("store: list checkpoints for commits %s: %w", storageRepoID, err)
	}
	shaB, err := shaBytesList(shas)
	if err != nil {
		return nil, fmt.Errorf("store: list checkpoints for commits %s: %w", codeRepoID, err)
	}
	args := []any{codeRid, storageRid, shaB, codeRepoID == storageRepoID}
	// dateWhere is spliced into the sel CTE's WHERE — i.e. BEFORE the DISTINCT ON
	// pick below. That ordering matters: a checkpoint linked to several commits,
	// some in-window and some not, must be judged by "does it have ANY reachable
	// commit in the window", with its anchor re-picked as the LATEST such
	// in-window commit. Filtering after the pick would instead judge the
	// checkpoint by whichever commit is latest overall, silently dropping a
	// checkpoint whose only in-window link isn't its most recent one. A NULL
	// commit_date row is excluded by either bound automatically (NULL >= x is
	// unknown, not true in SQL) — no explicit IS NOT NULL guard needed.
	//
	// anchorDateWhere bounds the anchor arm on cp.created_at (its cdate) with
	// the same $-positions, or windowed callers would get imports unfiltered.
	var dateWhere, anchorDateWhere string
	if since != nil {
		args = append(args, *since)
		pos := len(args)
		dateWhere += fmt.Sprintf(" AND cc.commit_date >= $%d", pos)
		anchorDateWhere += fmt.Sprintf(" AND cp.created_at >= $%d", pos)
	}
	if until != nil {
		args = append(args, *until)
		pos := len(args)
		dateWhere += fmt.Sprintf(" AND cc.commit_date < $%d", pos)
		anchorDateWhere += fmt.Sprintf(" AND cp.created_at < $%d", pos)
	}
	args = append(args, limit)
	limitPos := len(args)
	// Pick each checkpoint's latest linking commit within the reachable set (and,
	// if since/until are set, within that window), LIMIT to the page (thin id+date
	// set), THEN compose the heavy payload for those ids. Links (checkpoint_commits)
	// are keyed by the code repo ($1); the payload (checkpoints) by the storage
	// repo ($2).
	//
	// The anchor arm is self-hosted-only because external checkpoint metadata
	// does not identify its code repo. It dates imports by their original time.
	q := fmt.Sprintf(`WITH sel AS (
		SELECT DISTINCT ON (cc.checkpoint_id) cc.checkpoint_id AS cpid, cc.commit_sha AS csha, cc.commit_date AS cdate
		FROM checkpoint_commits cc
		WHERE cc.repo_id = $1 AND cc.commit_sha = ANY($3)%s
		ORDER BY cc.checkpoint_id, cc.commit_date DESC
	), anchor AS (
		SELECT cp.checkpoint_id AS cpid, cp.anchor_commit_sha AS csha, cp.created_at AS cdate
		FROM checkpoints cp
		WHERE $4 AND cp.repo_id = $2 AND cp.kind = 'imported' AND cp.anchor_commit_sha = ANY($3)
			AND cp.checkpoint_id NOT IN (SELECT cpid FROM sel)%s
	), combined AS (
		SELECT cpid, csha, cdate FROM sel
		UNION ALL
		SELECT cpid, csha, cdate FROM anchor
	), page AS (
		SELECT cpid, csha FROM combined ORDER BY cdate DESC NULLS LAST LIMIT $%d
	)
	SELECT `+checkpointWithCommitCols+`
	FROM page
	JOIN checkpoints cp ON cp.repo_id = $2 AND cp.checkpoint_id = page.cpid
	LEFT JOIN checkpoint_commits cc ON cc.repo_id = $1 AND cc.checkpoint_id = page.cpid AND cc.commit_sha = page.csha
	ORDER BY coalesce(cc.commit_date, cp.created_at) DESC NULLS LAST`, dateWhere, anchorDateWhere, limitPos)
	rows, err := s.pool.Query(ctx, q, args...)
	if err != nil {
		return nil, fmt.Errorf("store: list checkpoints for commits %s: %w", codeRepoID, err)
	}
	defer rows.Close()
	return scanCheckpointsWithCommit(rows)
}

// GetCheckpointComposed returns one checkpoint joined to its latest commit,
// ok=false if absent. Drives the checkpoint detail endpoint.
//
// Like ListCheckpointsForCommits, the join spans two repos: the payload
// (checkpoints) lives under the storage repo ($2) while the links
// (checkpoint_commits) live under the code repo ($1). checkpoint_id is
// content-keyed, so the link@code joins the payload@storage unambiguously. Pass
// storageRepoID == codeRepoID for a self-hosted repo (see CheckpointStorageRepoID).
func (s *RepoStore) GetCheckpointComposed(ctx context.Context, codeRepoID, storageRepoID, checkpointID string) (CheckpointWithCommit, bool, error) {
	codeRid, err := ulidBytes(codeRepoID)
	if err != nil {
		return CheckpointWithCommit{}, false, fmt.Errorf("store: get checkpoint composed %s/%s: %w", codeRepoID, checkpointID, err)
	}
	storageRid, err := ulidBytes(storageRepoID)
	if err != nil {
		return CheckpointWithCommit{}, false, fmt.Errorf("store: get checkpoint composed %s/%s: %w", storageRepoID, checkpointID, err)
	}
	// Linkless import detail is self-hosted-only; external storage cannot prove
	// which code repo owns the import.
	q := `SELECT DISTINCT ON (cp.checkpoint_id) ` + checkpointWithCommitCols + `
		FROM checkpoints cp
		LEFT JOIN checkpoint_commits cc ON cc.repo_id = $1 AND cc.checkpoint_id = cp.checkpoint_id
		WHERE cp.repo_id = $2 AND cp.checkpoint_id = $3
			AND (cc.checkpoint_id IS NOT NULL OR ($4 AND cp.kind = 'imported' AND cp.anchor_commit_sha IS NOT NULL))
		ORDER BY cp.checkpoint_id, cc.commit_date DESC NULLS LAST`
	rows, err := s.pool.Query(ctx, q, codeRid, storageRid, checkpointID, codeRepoID == storageRepoID)
	if err != nil {
		return CheckpointWithCommit{}, false, fmt.Errorf("store: get checkpoint composed %s/%s: %w", codeRepoID, checkpointID, err)
	}
	defer rows.Close()
	out, err := scanCheckpointsWithCommit(rows)
	if err != nil {
		return CheckpointWithCommit{}, false, err
	}
	if len(out) == 0 {
		return CheckpointWithCommit{}, false, nil
	}
	return out[0], true, nil
}

func scanCheckpointsWithCommit(rows pgx.Rows) ([]CheckpointWithCommit, error) {
	var out []CheckpointWithCommit
	for rows.Next() {
		var (
			c                                CheckpointWithCommit
			sessionsJSON, filesJSON          []byte
			commitSHA, commitAuthorAccountID []byte
			createdAt, committedAt           *time.Time
		)
		if err := rows.Scan(&c.CheckpointID, &createdAt, &sessionsJSON, &filesJSON,
			&c.InputTokens, &c.CacheCreationTokens, &c.CacheReadTokens, &c.OutputTokens, &c.APICallCount,
			&c.AttrAgentLines, &c.AttrHumanAdded, &c.AttrHumanModified, &c.AttrHumanRemoved,
			&c.AttrTotalCommitted, &c.AttrAgentPercentage, &c.AttrCalculatedAt,
			&commitSHA, &c.CommitAuthor, &committedAt,
			&c.Additions, &c.Deletions, &c.FilesChanged,
			&commitAuthorAccountID, &c.CommitAuthorGitHubLogin); err != nil {
			return nil, fmt.Errorf("store: scan checkpoint+commit: %w", err)
		}
		c.CommitSHA = shaText(commitSHA)
		c.CommitAuthorAccountID = ulidText(commitAuthorAccountID)
		if createdAt != nil {
			c.CreatedAt = *createdAt
		}
		if committedAt != nil {
			c.CommitDate = *committedAt
		}
		_ = json.Unmarshal(sessionsJSON, &c.Sessions)
		_ = json.Unmarshal(filesJSON, &c.FilesTouched)
		out = append(out, c)
	}
	return out, rows.Err()
}

// ContributingCheckpointSessions is one checkpoint that lists a session, with
// its parsed sessions[], for the session-transcript merge.
type ContributingCheckpointSessions struct {
	CheckpointID string
	Sessions     []SessionInfo
	// CreatedAt orders the contributing checkpoints; nil when the row has no
	// created_at yet (checkpoint-first ingest before its commit lands). The
	// merge uses it to pick the latest cumulative snapshot, falling back to
	// merging every checkpoint when any created_at is missing.
	CreatedAt *time.Time
	// RefBacked routes the per-session blob read (checkpointlayout.RefAndFolder):
	// true when this checkpoint's blobs live at its own ref, false on the v1
	// branch. Needed because a legacy hex id's shape can't reveal its backend.
	RefBacked bool
}

// ContributingCheckpointSessions returns, oldest-first (created_at), every
// checkpoint that lists sessionID in its session_ids, with its parsed
