// TestIntegrationCheckpointStorageAccessRedaction pins the preview-redaction gate
// the commits-list / commit-detail / compare endpoints rely on: those routes gate
// only on the code repo, so when checkpoints live in a SEPARATE repo the caller
// must additionally hold read on it to see the previews. checkpointStorageAccess
// returns canSee=false (redact) rather than erroring, so a code-repo-only reader
// gets commits without a leak of the stricter checkpoint repo's data.
func TestIntegrationCheckpointStorageAccessRedaction(t *testing.T) {
	repoStore, _ := openPipelineStores(t)
	ctx := auth.WithIdentity(context.Background(), &auth.Identity{Subject: auth.AccountSubject("acc1")})

	selfHosted := routeULID("self-hosted")
	code := routeULID("code-x")
	storage := routeULID("storage-x")

	// code → storage association (self-hosted repo has none, so it resolves to itself).
	if err := repoStore.UpsertRepo(ctx, store.Repo{ID: code, OwningProjectID: routeULID("proj"), Jurisdiction: "us"}); err != nil {
		t.Fatal(err)
	}
	if err := repoStore.SetCheckpointRepoID(ctx, code, storage); err != nil {
		t.Fatal(err)
	}

	deps := func(pullable ...string) *RepoActivityDeps {
		return NewRepoActivityDeps(config.Common{}, nil, fakeReaderRW(pullable, nil, nil, false), nil, repoStore, "")
	}

	// Self-hosted (storage == code): the route's own code-repo gate already
	// authorized it — canSee=true with no separate check, even granting nothing.
	if sid, canSee, err := deps().checkpointStorageAccess(ctx, selfHosted); err != nil || sid != selfHosted || !canSee {
		t.Fatalf("self-hosted = (%q, %v, %v); want (%q, true, nil)", sid, canSee, err, selfHosted)
	}

	// External storage, caller holds read on the CODE repo only → redact.
	if sid, canSee, err := deps(code).checkpointStorageAccess(ctx, code); err != nil || sid != storage || canSee {
		t.Fatalf("code-only = (%q, %v, %v); want (%q, false, nil)", sid, canSee, err, storage)
	}

	// External storage, caller also holds read on the STORAGE repo → full previews.
	if sid, canSee, err := deps(code, storage).checkpointStorageAccess(ctx, code); err != nil || sid != storage || !canSee {
		t.Fatalf("code+storage = (%q, %v, %v); want (%q, true, nil)", sid, canSee, err, storage)
	}
}

// TestIntegrationCheckpointAnalysisExternalStorageRepo guards the code→storage read
// for GET /repos/{id}/checkpoints/{cp}/analysis: the analysis row is keyed under the
// checkpoint STORAGE repo, so the handler must resolve code→storage before reading.
// Keying on the code repo (the pre-fix behaviour) finds no row and reports the
// analysis as not_available even when it is complete.
func TestIntegrationCheckpointAnalysisExternalStorageRepo(t *testing.T) {
	repoStore, _ := openPipelineStores(t)
	ctx := auth.WithIdentity(context.Background(), &auth.Identity{Subject: auth.AccountSubject("acc1")})

	code, storage := routeULID("ca-code"), routeULID("ca-storage")
	for _, id := range []string{code, storage} {
		if err := repoStore.UpsertRepo(ctx, store.Repo{ID: id, OwningProjectID: routeULID("proj"), Jurisdiction: "us"}); err != nil {
			t.Fatal(err)
		}
	}
	if err := repoStore.SetCheckpointRepoID(ctx, code, storage); err != nil {
		t.Fatal(err)
	}
	// A complete analysis row keyed under the STORAGE repo (labels_state=complete + a
	// non-empty blob), and nothing under the code repo.
	if _, err := repoStore.UpsertCheckpoint(ctx, store.Checkpoint{RepoID: storage, CheckpointID: "cp1", PrimaryAgent: "claude"}); err != nil {
		t.Fatal(err)
	}
	if err := repoStore.UpsertCheckpointLabels(ctx, storage, "cp1", nil, []byte(`{}`), "v1"); err != nil {
		t.Fatal(err)
	}

	deps := NewRepoActivityDeps(config.Common{}, nil, fakeReaderRW([]string{code, storage}, nil, nil, false), nil, repoStore, "")

	// The handler resolves code→storage and finds the row → status complete.
	out, err := checkpointAnalysis(ctx, deps, &CheckpointAnalysisInput{RepoID: code, CheckpointID: "cp1"})
	if err != nil {
		t.Fatal(err)
	}
	if out.Body.Status != "complete" {
		t.Errorf("analysis status = %q, want complete (read from the storage repo)", out.Body.Status)
	}

	// Guard: the row exists ONLY under the storage repo, so a code-keyed read finds
	// nothing — exactly what the pre-fix handler did (status not_available).
	if _, _, ok, err := repoStore.GetCheckpointAnalysisBlob(ctx, code, "cp1"); err != nil {
		t.Fatal(err)
	} else if ok {
		t.Fatal("analysis row unexpectedly present under the code repo; test can't prove the fix")
	}
}
