	}
	return out[0], true, nil
}

func scanCheckpointsWithCommit(rows pgx.Rows) ([]CheckpointWithCommit, error) {
	var out []CheckpointWithCommit
	for rows.Next() {
		var (
			c                                CheckpointWithCommit
			sessionsJSON, filesJSON          []byte
			commitSHA, commitAuthorAccountID []byte
			createdAt, committedAt           *time.Time
		)
		if err := rows.Scan(&c.CheckpointID, &createdAt, &sessionsJSON, &filesJSON,
			&c.InputTokens, &c.CacheCreationTokens, &c.CacheReadTokens, &c.OutputTokens, &c.APICallCount,
			&c.AttrAgentLines, &c.AttrHumanAdded, &c.AttrHumanModified, &c.AttrHumanRemoved,
			&c.AttrTotalCommitted, &c.AttrAgentPercentage, &c.AttrCalculatedAt,
			&commitSHA, &c.CommitAuthor, &committedAt,
			&c.Additions, &c.Deletions, &c.FilesChanged,
			&commitAuthorAccountID, &c.CommitAuthorGitHubLogin); err != nil {
			return nil, fmt.Errorf("store: scan checkpoint+commit: %w", err)
		}
		c.CommitSHA = shaText(commitSHA)
		c.CommitAuthorAccountID = ulidText(commitAuthorAccountID)
		if createdAt != nil {
			c.CreatedAt = *createdAt
		}
		if committedAt != nil {
			c.CommitDate = *committedAt
