	// nothing — exactly what the pre-fix handler did (status not_available).
	if _, _, ok, err := repoStore.GetCheckpointAnalysisBlob(ctx, code, "cp1"); err != nil {
		t.Fatal(err)
	} else if ok {
		t.Fatal("analysis row unexpectedly present under the code repo; test can't prove the fix")
	}
}
