// nor mask a genuine retrieval failure once refs are known to resolve.
func TestRouteSessionsUnpushedBranchEmptyVsMissingRepo404(t *testing.T) {
	f, _, repoID, _ := newRepoAPIFixture(t, true, false)

	// A repo the caller is authorized on but that isn't in this region at all
	// (the trail itself doesn't exist here) must still 404 — the route's
	// access gate runs before the handler ever resolves base/head.
	absentRepoID := routeULID("absent-" + uniqueSuffix())
	origReader := f.deps.Reader
	f.deps.Reader = fakeReaderRW([]string{repoID, absentRepoID}, nil, nil, false)
	t.Cleanup(func() { f.deps.Reader = origReader })
	absentPath := "/api/v1/repos/" + absentRepoID + "/sessions?base=main&head=never-pushed"
	if code := f.get(t, absentPath, true, nil); code != http.StatusNotFound {
		t.Errorf("authorized but absent repo = %d, want 404", code)
	}

	// The other edge: the empty-not-error conversion belongs to the ref lookup
	// only. Once CompareStatus has resolved both refs and claimed commits ahead,
	// a not-found from the window walk means the delta could not be enumerated —
	// an unreadable range, not an empty one. Reporting 200 + empty here would let
	// a retrieval failure masquerade as "this trail has no sessions", the exact
	// confusion this fix exists to remove.
	f.setCompareStatus(repoapi.CompareStatus{CommitsAhead: 2})
	f.setForceCommitsNotFound(true)
	t.Cleanup(func() { f.setForceCommitsNotFound(false) })
	if code := f.get(t, "/api/v1/repos/"+repoID+"/sessions?base=main&head=feature", true, nil); code == http.StatusOK {
		t.Errorf("unenumerable delta = 200, want an error status")
	}
}

