 for(const mode of ["fork","dedicated","no-remotes","missing-remote"]) cases.push({name:`${backend}-${mode}`,backend,mode,disabled:true});
}
cases.push({name:"local-disables",mode:"fork",disabled:true,shared:true,local:false},
{name:"local-enables",mode:"fork",disabled:false,shared:false,local:true},
{name:"enabled-control",mode:"fork",disabled:false,shared:true},
{name:"default-control",mode:"fork",disabled:false,omit:true},
{name:"entire-disabled",mode:"fork",disabled:false,entireDisabled:true});
let patch="*** Begin Patch\n";
function add(path,content){patch+="*** Add File: "+path+"\n"+content.trimEnd().split("\n").map(l=>"+"+l).join("\n")+"\n";}
for(const c of cases){
 const opts={};
 if(!c.omit)opts.push_sessions=c.shared??false;
 if(c.mode==="fork")opts.checkpoint_push_remote="fork";
 if(c.mode==="missing-remote")opts.checkpoint_push_remote="gone";
 if(c.mode==="dedicated")opts.checkpoint_remote={provider:"github",repo:"org/checkpoints"};
 add(`${root}/${c.name}/.entire/settings.json`,JSON.stringify({enabled:!c.entireDisabled,strategy_options:opts,checkpoints:{primary:{type:c.backend??"git-refs"}}},null,2));
 if(c.local!==undefined)add(`${root}/${c.name}/.entire/settings.local.json`,JSON.stringify({strategy_options:{push_sessions:c.local}},null,2));
 add(`${root}/${c.name}/.gitignore`,".entire/\n");
 add(`${root}/${c.name}/seed.txt`,"status smoke fixture\n");
}
add(`${root}/cases.json`,JSON.stringify(cases,null,2));
add(`${root}/smoke.mjs`,`
import {spawnSync} from 'node:child_process';
import {readFileSync} from 'node:fs';
import assert from 'node:assert/strict';
const root = ${JSON.stringify(root)};
const cases = JSON.parse(readFileSync(root+'/cases.json','utf8'));
const env = {PATH:process.env.PATH, TMPDIR:process.env.TMPDIR, LANG:'C', LC_ALL:'C',
 GIT_CONFIG_NOSYSTEM:'1', GIT_CONFIG_GLOBAL:'/dev/null', GIT_TERMINAL_PROMPT:'0',
 ENTIRE_CONFIG_DIR:root+'/config', XDG_CACHE_HOME:root+'/cache',
 ENTIRE_TOKEN_STORE:'file', ENTIRE_TOKEN_STORE_PATH:root+'/tokens.json',
 ENTIRE_TEST_AUTH_STORE_FILE:root+'/auth.json', ENTIRE_TEST_TTY:'0', DO_NOT_TRACK:'1'};
function run(cmd,args,cwd) {
 const p=spawnSync(cmd,args,{cwd,env,encoding:'utf8',timeout:30000});
 assert.equal(p.status,0,cmd+' '+args.join(' ')+'\\n'+p.stdout+'\\n'+p.stderr+'\\n'+(p.error??''));
 return p.stdout;
}
let commands=0;
for(const c of cases) {
 const cwd=root+'/'+c.name;
 const git=(...args)=>run('git',args,cwd);
 git('init','-q');
 git('config','user.name','Smoke Test');
 git('config','user.email','smoke@example.invalid');
 git('config','commit.gpgsign','false');
 git('config','core.hooksPath',root+'/no-hooks');
 git('add','seed.txt','.gitignore');
 git('commit','--no-gpg-sign','-qm','fixture');
 if(c.mode!=='no-remotes') git('remote','add','origin','https://github.com/org/repo.git');
 if(c.mode==='fork') git('remote','add','fork','https://github.com/user/repo.git');
 const before=git('status','--porcelain');
 for(const flags of [[],['--detailed'],['--json']]) {
   const out=run(root+'/entire',['status',...flags],cwd);
   commands++;
   if(flags.includes('--json')) {
     const result=JSON.parse(out);
     assert.equal(result.enabled,!c.entireDisabled);
     if(c.disabled) {
       assert.equal(result.checkpoint_push_disabled,true);
       for(const key of ['checkpoint_sync_remote','checkpoint_sync_remote_source','checkpoint_sync_error','unpushed_checkpoints','checkpoint_remote_ignored','checkpoint_remote_ignored_reason']) assert.equal(key in result,false,key+' must be absent');
     } else {
       assert.equal('checkpoint_push_disabled' in result,false);
       if(!c.entireDisabled) assert.equal(result.checkpoint_sync_remote,'fork');
     }
   } else if(c.disabled) {
     assert.ok(out.includes('Automatic checkpoint pushing: disabled (push_sessions=false)'),out);
     for(const text of ['Checkpoints sync to:','Checkpoints NOT syncing:',"next 'git push",'is not in use:']) assert.ok(!out.includes(text),out);
   } else {
     assert.ok(!out.includes('Automatic checkpoint pushing: disabled'),out);
     if(!c.entireDisabled)assert.ok(out.includes('Checkpoints sync to: fork'),out);
   }
   if(c.name==='git-refs-fork') console.log('ACTUAL '+['status',...flags].join(' ')+'\\n'+out);
 }
 assert.equal(git('status','--porcelain'),before,'status changed tracked files');
 console.log('PASS '+c.name+' (text, detailed, JSON)');
}
console.log('PASS: '+cases.length+' scenarios, '+commands+' actual CLI invocations; no pushes.');
`);
patch+="*** End Patch";
text(await tools.apply_patch(patch));

