func must(err error) {
	if err != nil {
		panic(err)
	}
}
func git(args ...string) string {
	b, e := exec.Command("git", args...).CombinedOutput()
	if e != nil {
		panic(fmt.Sprintf("git %v: %v %s", args, e, b))
	}
	return strings.TrimSpace(string(b))
}
func main() {
	root := os.Args[1]
	name := os.Args[2]
	dir := filepath.Join(root, name)
	must(os.Chdir(dir))
	must(os.Setenv("REPRO_CASE", dir))
	ctx := context.Background()
	git("init", "-q")
	git("config", "user.name", "Repro")
	git("config", "user.email", "repro@example.invalid")
	git("config", "commit.gpgsign", "false")
	git("config", "core.hooksPath", "/dev/null")
	git("add", ".entire/settings.json")
	git("commit", "-q", "--no-gpg-sign", "-m", "fixture")
	for _, n := range []string{"origin", "fork", "dedicated", "backup"} {
		git("init", "--bare", "-q", dir+"/"+n+".git")
	}
	git("remote", "add", "origin", "https://github.com/acme/app.git")
	git("remote", "add", "fork", "https://github.com/contributor/app.git")
	switch name {
	case "nonorigin_no_origin":
		git("remote", "remove", "origin")
	case "nonorigin_split":
		git("remote", "set-url", "--push", "fork", "https://github.com/contributor/backup.git")
	case "nonorigin_multi":
		git("remote", "set-url", "--add", "--push", "fork", "https://github.com/contributor/app.git")
		git("remote", "set-url", "--add", "--push", "fork", "https://github.com/contributor/backup.git")
	case "nonorigin_capture":
		git("config", "remote.pushDefault", "fork")
	case "nonorigin_explicit_beats_tracking":
		git("config", "remote.pushDefault", "origin")
	case "nonorigin_renamed":
		git("remote", "rename", "fork", "renamed")
	case "nonorigin_origin_unreachable":
		git("remote", "set-url", "origin", "https://github.com/missing/app.git")
	}
	repo, e := gitrepo.OpenCurrent(ctx)
	must(e)
	defer repo.Close()
	stores, e := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{})
	must(e)
	cid := id.CheckpointID("01KVBJCWYA4YW6J5M9GP655HZN")
	must(stores.Persistent.Write(ctx, checkpoint.Session{CheckpointID: cid, SessionID: "repro-session", Strategy: "manual-commit", Transcript: redact.AlreadyRedacted([]byte("synthetic reproduction transcript")), Prompts: []string{"synthetic reproduction"}, AuthorName: "Repro", AuthorEmail: "repro@example.invalid"}))
	ref, e := checkpoint.RefName(cid)
	must(e)
	must(checkpoint.NewPushQueue(dir + "/.git").Enqueue(ref))
	if name == "nonorigin_legacy" {
		git("push", "origin", ref.String()+":"+ref.String())
	}
	status, e := exec.Command("/private/tmp/entire-remote-trace-20260908", "status", "--json").Output()
	must(e)
	var s map[string]any
	must(json.Unmarshal(status, &s))
	for k := range s {
		if !strings.Contains(k, "checkpoint") {
			delete(s, k)
		}
	}
	target := "fork"
	if name == "conflict" {
		target = "origin"
	}
	if name == "nonorigin_push_origin" {
		target = "origin"
	}
	if name == "nonorigin_raw_push" {
		target = "https://github.com/contributor/app.git"
	}
	if name == "nonorigin_renamed" {
		target = "renamed"
	}
	pushURL, dedicated, e := remote.PushURL(ctx, target)
	must(e)
	resolution := strategy.CheckpointReadRemotesWithElection(ctx)
	fetchURL, _ := remote.FetchURL(ctx, remote.FetchURLOptions{LeadReadRemote: resolution.ElectedName})
	before, e := cli.ListCheckpointRefsOnRemote(ctx)
	must(e)
	must((&strategy.ManualCommitStrategy{}).PrePush(ctx, target))
	after, e := cli.ListCheckpointRefsOnRemote(ctx)
	must(e)
	deliveries := map[string]string{}
	for _, n := range []string{"origin", "fork", "dedicated", "backup"} {
		deliveries[n] = git("--git-dir="+dir+"/"+n+".git", "for-each-ref", "--format=%(refname)", "refs/entire/")
	}
	queue, e := checkpoint.NewPushQueue(dir + "/.git").Peek()
	must(e)
	result := map[string]any{"case": name, "status": s, "push_remote": target, "dedicated_enabled": dedicated, "push_url_helper": pushURL, "fetch_url_helper": fetchURL, "discovered_before": len(before), "discovered_after": len(after), "remote_refs": deliveries, "queued_after": len(queue)}
	postStatus, e := exec.Command("/private/tmp/entire-remote-trace-20260908", "status", "--json").Output()
	must(e)
	var post map[string]any
	must(json.Unmarshal(postStatus, &post))
	for k := range post {
		if !strings.Contains(k, "checkpoint") {
			delete(post, k)
		}
	}
	result["status_after"] = post
	result["read_candidates"] = resolution.Candidates
	if name == "explicit" {
		out, _ := exec.Command("/private/tmp/entire-remote-trace-20260908", "doctor").CombinedOutput()
		text := string(out)
		if i := strings.Index(text, "Checkpoint destination:"); i >= 0 {
			result["doctor_destination"] = text[i:]
		}
	}
	b, e := json.MarshalIndent(result, "", "  ")
	must(e)
	fmt.Println(string(b))
}

