	testutil.RunGit(t, env.RepoDir, "remote", "set-url", "origin", "https://github.com/acme/app.git")
	testutil.RunGit(t, env.RepoDir, "remote", "set-url", "fork", "https://github.com/contributor/app.git")
	env.setGitConfigBaseline()
